package com.certimaster.learning.adapter.web.response;

import java.io.Serial;
import java.io.Serializable;
import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.List;

/**
 * Response containing exam results.
 * Sent from result-service back to exam-service via Kafka reply pattern.
 */
public class ExamResultResponse implements Serializable {

    @Serial
    private static final long serialVersionUID = 1L;

    /**
     * Result ID generated by result-service.
     */
    private Long resultId;

    /**
     * Session ID from exam-service.
     */
    private Long sessionId;

    /**
     * User ID.
     */
    private Long userId;

    /**
     * Exam ID.
     */
    private Long examId;

    /**
     * Exam title.
     */
    private String examTitle;

    /**
     * Total number of questions.
     */
    private Integer totalQuestions;

    /**
     * Number of correct answers.
     */
    private Integer correctAnswers;

    /**
     * Number of wrong answers.
     */
    private Integer wrongAnswers;

    /**
     * Number of unanswered questions.
     */
    private Integer unanswered;

    /**
     * Raw score (number of correct answers).
     */
    private BigDecimal score;

    /**
     * Score percentage.
     */
    private BigDecimal percentage;

    /**
     * Pass/fail status (PASSED or FAILED).
     */
    private String passStatus;

    /**
     * Exam mode (PRACTICE or TIMED).
     */
    private String mode;

    /**
     * Passing score percentage required.
     */
    private Integer passingScore;

    /**
     * Total time taken in seconds.
     */
    private Integer timeTakenSeconds;

    /**
     * When the exam was completed.
     */
    private LocalDateTime completedAt;

    /**
     * Topic-wise performance breakdown.
     */
    private List<TopicPerformanceData> topicPerformances;

    /**
     * Per-question results with explanations.
     */
    private List<QuestionResultData> questionResults;

    /**
     * Whether result calculation was successful.
     */
    private boolean success;

    /**
     * Error message if calculation failed.
     */
    private String errorMessage;

    public ExamResultResponse() {
    }

    public ExamResultResponse(Long resultId, Long sessionId, Long userId, Long examId,
                              String examTitle, Integer totalQuestions, Integer correctAnswers,
                              Integer wrongAnswers, Integer unanswered, BigDecimal score,
                              BigDecimal percentage, String passStatus, Integer passingScore,
                              Integer timeTakenSeconds, LocalDateTime completedAt,
                              List<TopicPerformanceData> topicPerformances,
                              List<QuestionResultData> questionResults,
                              boolean success, String errorMessage) {
        this.resultId = resultId;
        this.sessionId = sessionId;
        this.userId = userId;
        this.examId = examId;
        this.examTitle = examTitle;
        this.totalQuestions = totalQuestions;
        this.correctAnswers = correctAnswers;
        this.wrongAnswers = wrongAnswers;
        this.unanswered = unanswered;
        this.score = score;
        this.percentage = percentage;
        this.passStatus = passStatus;
        this.passingScore = passingScore;
        this.timeTakenSeconds = timeTakenSeconds;
        this.completedAt = completedAt;
        this.topicPerformances = topicPerformances;
        this.questionResults = questionResults;
        this.success = success;
        this.errorMessage = errorMessage;
    }

    public static Builder builder() {
        return new Builder();
    }

    public static class Builder {
        private Long resultId;
        private Long sessionId;
        private Long userId;
        private Long examId;
        private String examTitle;
        private Integer totalQuestions;
        private Integer correctAnswers;
        private Integer wrongAnswers;
        private Integer unanswered;
        private BigDecimal score;
        private BigDecimal percentage;
        private String passStatus;
        private String mode;
        private Integer passingScore;
        private Integer timeTakenSeconds;
        private LocalDateTime completedAt;
        private List<TopicPerformanceData> topicPerformances;
        private List<QuestionResultData> questionResults;
        private boolean success;
        private String errorMessage;

        public Builder resultId(Long v) { this.resultId = v; return this; }
        public Builder sessionId(Long v) { this.sessionId = v; return this; }
        public Builder userId(Long v) { this.userId = v; return this; }
        public Builder examId(Long v) { this.examId = v; return this; }
        public Builder examTitle(String v) { this.examTitle = v; return this; }
        public Builder totalQuestions(Integer v) { this.totalQuestions = v; return this; }
        public Builder correctAnswers(Integer v) { this.correctAnswers = v; return this; }
        public Builder wrongAnswers(Integer v) { this.wrongAnswers = v; return this; }
        public Builder unanswered(Integer v) { this.unanswered = v; return this; }
        public Builder score(BigDecimal v) { this.score = v; return this; }
        public Builder percentage(BigDecimal v) { this.percentage = v; return this; }
        public Builder passStatus(String v) { this.passStatus = v; return this; }
        public Builder mode(String v) { this.mode = v; return this; }
        public Builder passingScore(Integer v) { this.passingScore = v; return this; }
        public Builder timeTakenSeconds(Integer v) { this.timeTakenSeconds = v; return this; }
        public Builder completedAt(LocalDateTime v) { this.completedAt = v; return this; }
        public Builder topicPerformances(List<TopicPerformanceData> v) { this.topicPerformances = v; return this; }
        public Builder questionResults(List<QuestionResultData> v) { this.questionResults = v; return this; }
        public Builder success(boolean v) { this.success = v; return this; }
        public Builder errorMessage(String v) { this.errorMessage = v; return this; }

        public ExamResultResponse build() {
            ExamResultResponse o = new ExamResultResponse();
            o.resultId = this.resultId;
            o.sessionId = this.sessionId;
            o.userId = this.userId;
            o.examId = this.examId;
            o.examTitle = this.examTitle;
            o.totalQuestions = this.totalQuestions;
            o.correctAnswers = this.correctAnswers;
            o.wrongAnswers = this.wrongAnswers;
            o.unanswered = this.unanswered;
            o.score = this.score;
            o.percentage = this.percentage;
            o.passStatus = this.passStatus;
            o.mode = this.mode;
            o.passingScore = this.passingScore;
            o.timeTakenSeconds = this.timeTakenSeconds;
            o.completedAt = this.completedAt;
            o.topicPerformances = this.topicPerformances;
            o.questionResults = this.questionResults;
            o.success = this.success;
            o.errorMessage = this.errorMessage;
            return o;
        }
    }

    public Long getResultId() { return resultId; }
    public void setResultId(Long resultId) { this.resultId = resultId; }

    public Long getSessionId() { return sessionId; }
    public void setSessionId(Long sessionId) { this.sessionId = sessionId; }

    public Long getUserId() { return userId; }
    public void setUserId(Long userId) { this.userId = userId; }

    public Long getExamId() { return examId; }
    public void setExamId(Long examId) { this.examId = examId; }

    public String getExamTitle() { return examTitle; }
    public void setExamTitle(String examTitle) { this.examTitle = examTitle; }

    public Integer getTotalQuestions() { return totalQuestions; }
    public void setTotalQuestions(Integer totalQuestions) { this.totalQuestions = totalQuestions; }

    public Integer getCorrectAnswers() { return correctAnswers; }
    public void setCorrectAnswers(Integer correctAnswers) { this.correctAnswers = correctAnswers; }

    public Integer getWrongAnswers() { return wrongAnswers; }
    public void setWrongAnswers(Integer wrongAnswers) { this.wrongAnswers = wrongAnswers; }

    public Integer getUnanswered() { return unanswered; }
    public void setUnanswered(Integer unanswered) { this.unanswered = unanswered; }

    public BigDecimal getScore() { return score; }
    public void setScore(BigDecimal score) { this.score = score; }

    public BigDecimal getPercentage() { return percentage; }
    public void setPercentage(BigDecimal percentage) { this.percentage = percentage; }

    public String getPassStatus() { return passStatus; }
    public void setPassStatus(String passStatus) { this.passStatus = passStatus; }

    public String getMode() { return mode; }
    public void setMode(String mode) { this.mode = mode; }

    public Integer getPassingScore() { return passingScore; }
    public void setPassingScore(Integer passingScore) { this.passingScore = passingScore; }

    public Integer getTimeTakenSeconds() { return timeTakenSeconds; }
    public void setTimeTakenSeconds(Integer timeTakenSeconds) { this.timeTakenSeconds = timeTakenSeconds; }

    public LocalDateTime getCompletedAt() { return completedAt; }
    public void setCompletedAt(LocalDateTime completedAt) { this.completedAt = completedAt; }

    public List<TopicPerformanceData> getTopicPerformances() { return topicPerformances; }
    public void setTopicPerformances(List<TopicPerformanceData> topicPerformances) { this.topicPerformances = topicPerformances; }

    public List<QuestionResultData> getQuestionResults() { return questionResults; }
    public void setQuestionResults(List<QuestionResultData> questionResults) { this.questionResults = questionResults; }

    public boolean isSuccess() { return success; }
    public void setSuccess(boolean success) { this.success = success; }

    public String getErrorMessage() { return errorMessage; }
    public void setErrorMessage(String errorMessage) { this.errorMessage = errorMessage; }

    /**
     * Topic performance data.
     */
    public static class TopicPerformanceData implements Serializable {

        @Serial
        private static final long serialVersionUID = 1L;

        /**
         * Topic ID.
         */
        private Long topicId;

        /**
         * Topic name.
         */
        private String topicName;

        /**
         * Total questions in this topic.
         */
        private Integer totalQuestions;

        /**
         * Correct answers in this topic.
         */
        private Integer correctAnswers;

        /**
         * Performance percentage for this topic.
         */
        private BigDecimal percentage;

        public TopicPerformanceData() {
        }

        public TopicPerformanceData(Long topicId, String topicName, Integer totalQuestions,
                                    Integer correctAnswers, BigDecimal percentage) {
            this.topicId = topicId;
            this.topicName = topicName;
            this.totalQuestions = totalQuestions;
            this.correctAnswers = correctAnswers;
            this.percentage = percentage;
        }

        public static Builder builder() {
            return new Builder();
        }

        public static class Builder {
            private Long topicId;
            private String topicName;
            private Integer totalQuestions;
            private Integer correctAnswers;
            private BigDecimal percentage;

            public Builder topicId(Long v) { this.topicId = v; return this; }
            public Builder topicName(String v) { this.topicName = v; return this; }
            public Builder totalQuestions(Integer v) { this.totalQuestions = v; return this; }
            public Builder correctAnswers(Integer v) { this.correctAnswers = v; return this; }
            public Builder percentage(BigDecimal v) { this.percentage = v; return this; }

            public TopicPerformanceData build() {
                TopicPerformanceData o = new TopicPerformanceData();
                o.topicId = this.topicId;
                o.topicName = this.topicName;
                o.totalQuestions = this.totalQuestions;
                o.correctAnswers = this.correctAnswers;
                o.percentage = this.percentage;
                return o;
            }
        }

        public Long getTopicId() { return topicId; }
        public void setTopicId(Long topicId) { this.topicId = topicId; }

        public String getTopicName() { return topicName; }
        public void setTopicName(String topicName) { this.topicName = topicName; }

        public Integer getTotalQuestions() { return totalQuestions; }
        public void setTotalQuestions(Integer totalQuestions) { this.totalQuestions = totalQuestions; }

        public Integer getCorrectAnswers() { return correctAnswers; }
        public void setCorrectAnswers(Integer correctAnswers) { this.correctAnswers = correctAnswers; }

        public BigDecimal getPercentage() { return percentage; }
        public void setPercentage(BigDecimal percentage) { this.percentage = percentage; }
    }

    /**
     * Per-question result data.
     */
    public static class QuestionResultData implements Serializable {

        @Serial
        private static final long serialVersionUID = 1L;

        /**
         * Question ID.
         */
        private Long questionId;

        /**
         * Question text.
         */
        private String questionText;

        /**
         * User's selected answer IDs.
         */
        private Long[] userAnswerIds;

        /**
         * Correct answer IDs.
         */
        private Long[] correctAnswerIds;

        /**
         * Whether the answer was correct.
         */
        private Boolean isCorrect;

        /**
         * Time spent on this question in seconds.
         */
        private Integer timeSpentSeconds;

        /**
         * Explanation for the correct answer.
         */
        private String explanation;

        /**
         * Reference material for further study.
         */
        private String reference;

        public QuestionResultData() {
        }

        public QuestionResultData(Long questionId, String questionText, Long[] userAnswerIds,
                                  Long[] correctAnswerIds, Boolean isCorrect,
                                  Integer timeSpentSeconds, String explanation, String reference) {
            this.questionId = questionId;
            this.questionText = questionText;
            this.userAnswerIds = userAnswerIds;
            this.correctAnswerIds = correctAnswerIds;
            this.isCorrect = isCorrect;
            this.timeSpentSeconds = timeSpentSeconds;
            this.explanation = explanation;
            this.reference = reference;
        }

        public static Builder builder() {
            return new Builder();
        }

        public static class Builder {
            private Long questionId;
            private String questionText;
            private Long[] userAnswerIds;
            private Long[] correctAnswerIds;
            private Boolean isCorrect;
            private Integer timeSpentSeconds;
            private String explanation;
            private String reference;

            public Builder questionId(Long v) { this.questionId = v; return this; }
            public Builder questionText(String v) { this.questionText = v; return this; }
            public Builder userAnswerIds(Long[] v) { this.userAnswerIds = v; return this; }
            public Builder correctAnswerIds(Long[] v) { this.correctAnswerIds = v; return this; }
            public Builder isCorrect(Boolean v) { this.isCorrect = v; return this; }
            public Builder timeSpentSeconds(Integer v) { this.timeSpentSeconds = v; return this; }
            public Builder explanation(String v) { this.explanation = v; return this; }
            public Builder reference(String v) { this.reference = v; return this; }

            public QuestionResultData build() {
                QuestionResultData o = new QuestionResultData();
                o.questionId = this.questionId;
                o.questionText = this.questionText;
                o.userAnswerIds = this.userAnswerIds;
                o.correctAnswerIds = this.correctAnswerIds;
                o.isCorrect = this.isCorrect;
                o.timeSpentSeconds = this.timeSpentSeconds;
                o.explanation = this.explanation;
                o.reference = this.reference;
                return o;
            }
        }

        public Long getQuestionId() { return questionId; }
        public void setQuestionId(Long questionId) { this.questionId = questionId; }

        public String getQuestionText() { return questionText; }
        public void setQuestionText(String questionText) { this.questionText = questionText; }

        public Long[] getUserAnswerIds() { return userAnswerIds; }
        public void setUserAnswerIds(Long[] userAnswerIds) { this.userAnswerIds = userAnswerIds; }

        public Long[] getCorrectAnswerIds() { return correctAnswerIds; }
        public void setCorrectAnswerIds(Long[] correctAnswerIds) { this.correctAnswerIds = correctAnswerIds; }

        public Boolean getIsCorrect() { return isCorrect; }
        public void setIsCorrect(Boolean isCorrect) { this.isCorrect = isCorrect; }

        public Integer getTimeSpentSeconds() { return timeSpentSeconds; }
        public void setTimeSpentSeconds(Integer timeSpentSeconds) { this.timeSpentSeconds = timeSpentSeconds; }

        public String getExplanation() { return explanation; }
        public void setExplanation(String explanation) { this.explanation = explanation; }

        public String getReference() { return reference; }
        public void setReference(String reference) { this.reference = reference; }
    }
}
